window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[251]={"id":"251","numero":251,"titre":"Amaigrissement","objectifs":[{"id":"251-1","rang":"B","rubrique":"Épidémiologie","titre":"Connaître les quatre principaux mécanismes responsables d'un amaigrissement","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> L'<span class=\"kw-clinique\">amaigrissement</span> est une <span class=\"kw-def\">perte de poids</span> — perte de <span class=\"kw-clinique\">masse</span> intracellulaire, répartie de façon harmonieuse ou non — de caractère <strong>dynamique et évolutif</strong>. <span class=\"kw-alerte\">Une perte de poids de 5 kg est toujours significative</span>, qu'elle soit volontaire ou involontaire (on peut parler d'amaigrissement même chez un obèse).</div>\n      <p>L'<span class=\"kw-clinique\">amaigrissement</span> témoigne d'un <strong>déséquilibre de la balance énergétique</strong> : des apports alimentaires <span class=\"kw-bio\">inférieurs aux dépenses énergétiques</span>. Quatre mécanismes peuvent y conduire.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>1 · Diminution des ingesta</strong></span></td>\n            <td>↓ des apports alimentaires — <span class=\"kw-alerte\">cause la plus fréquente</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>2 · Malabsorption / maldigestion</strong></span></td>\n            <td>Défaut d'assimilation, <strong>souvent accompagné de signes digestifs</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>3 · Pertes caloriques et/ou protéiques</strong></span></td>\n            <td>Glycosurie, <span class=\"kw-clinique\">syndrome néphrotique</span>, entéropathies exsudatives…</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>4 · Augmentation des dépenses énergétiques</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Activité physique</span></li>\n                <li><span class=\"kw-clinique\">Thermorégulation</span> (frisson, sudation)</li>\n                <li><span class=\"kw-clinique\">Maladies aiguës ou chroniques</span></li>\n                <li><span class=\"kw-clinique\">Traitements</span> (<span class=\"kw-ttt\">chirurgie</span>, <span class=\"kw-ttt\">chimiothérapie</span>, radiothérapie)</li>\n                <li>Phénomènes de <span class=\"kw-clinique\">réparation, cicatrisation</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"251-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les quatre principales causes d'un amaigrissement","contenu":"<p>Les causes d'<span class=\"kw-clinique\">amaigrissement</span> se répartissent en <strong>grandes catégories</strong>. La distinction se fait ensuite sur le comportement alimentaire (cf. raisonnement diagnostique).</p>\n\n      <div class=\"callout callout-danger\"><strong>Causes organiques +++</strong>\n        <ul>\n          <li><span class=\"kw-clinique\"><strong>Cancers</strong></span> : digestifs et ORL <span class=\"kw-chiffre\">+++</span></li>\n          <li><span class=\"kw-clinique\"><strong>Malabsorption / maldigestion</strong></span> : insuffisance pancréatique, pathologies biliaires, maladie cœliaque, MICI, parasitose, résection digestive…</li>\n          <li><span class=\"kw-clinique\"><strong>Maladies neurologiques</strong></span> : Parkinson, SEP, <span class=\"kw-alerte\">AVC</span>, démence…</li>\n          <li><span class=\"kw-clinique\"><strong>Infectieux</strong></span> : <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">VIH</span>, état septique chronique</li>\n          <li><span class=\"kw-clinique\"><strong>Endocrinopathies</strong></span> : hyperthyroïdie, <span class=\"kw-etio\">diabète</span> décompensé, hyperparathyroïdie, phéochromocytome, insuffisance antéhypophysaire, insuffisance surrénale aiguë</li>\n          <li><span class=\"kw-clinique\"><strong>Maladies auto-immunes</strong></span> : lupus, sarcoïdose, maladie de Horton</li>\n          <li><span class=\"kw-clinique\"><strong>Insuffisances d'organe</strong></span> : cardiaque, respiratoire, rénale…</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\"><strong>Causes psychiatriques</strong>\n        <ul>\n          <li>Baisse des ingesta, manœuvres de purges, augmentation de l'activité physique</li>\n          <li>Syndrome dépressif</li>\n          <li>Troubles du comportement alimentaire (<span class=\"kw-bio\">TCA</span>)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\"><strong>Causes socio-environnementales</strong>\n        <ul>\n          <li>Difficulté d'accès aux aliments ou négligence vis-à-vis de l'alimentation</li>\n          <li>Alcoolisme, toxicomanie</li>\n          <li>Solitude</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\"><strong>Cause <span class=\"kw-etio\">iatrogène</span></strong> — médicaments diminuant l'appétit : <span class=\"kw-ttt\">chimiothérapie</span>, <span class=\"kw-ttt\">morphiniques</span>, <span class=\"kw-ttt\">antidépresseurs</span>.</div>\n\n      <p><strong><span class=\"kw-clinique\">Amaigrissement</span> volontaire non psychiatrique</strong> : régime restrictif pour raisons médicales, esthétiques ou revendicatrices.</p>","frequence":0},{"id":"251-3","rang":"B","rubrique":"Physiopathologie","titre":"Savoir porter le diagnostic positif et différentiel d'un amaigrissement","contenu":"<p><strong><span class=\"kw-def\">Diagnostic positif</span></strong> — affirmer l'<span class=\"kw-clinique\">amaigrissement</span> par la <span class=\"kw-def\">pesée du patient</span>.</p>\n      <ul>\n        <li>Pesée fiable : <strong>vessie vide, en sous-vêtements, balance fiable</strong></li>\n        <li>Perte exprimée en <span class=\"kw-bio\">% du poids habituel</span> ; <span class=\"kw-alerte\">une perte de 5 kg est toujours significative</span></li>\n        <li><strong>À l'admission puis hebdomadaire</strong> en hospitalier, voire quotidienne si dénutrition sévère chez l'enfant</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Seuils de significativité.</strong>\n        <ul>\n          <li><span class=\"kw-chiffre\">&gt; 5 %</span> en <span class=\"kw-chiffre\">1 mois</span></li>\n          <li><span class=\"kw-chiffre\">&gt; 10 %</span> en <span class=\"kw-chiffre\">6 mois</span></li>\n          <li><span class=\"kw-chiffre\">&gt; 10 %</span> par rapport au poids habituel avant le début de la maladie</li>\n        </ul>\n        🚩 <strong>Chez l'enfant</strong> : analyser impérativement les courbes de poids ET de taille — un ralentissement de la courbe de croissance peut précéder la stagnation/perte pondérale.\n      </div>\n\n      <p style=\"margin-top:18px\"><strong><span class=\"kw-def\">Diagnostic différentiel</span></strong> — ce qui n'est PAS un <span class=\"kw-clinique\">amaigrissement</span>.</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Perte de poids par <strong>mouvement hydrique</strong></span> : la perte d'un <span class=\"kw-clinique\">œdème</span> <span class=\"kw-alerte\">≠ amaigrissement</span></li>\n      </ul>\n      <div class=\"obj-callout success\" style=\"border-left:4px solid var(--spe-pneumo,#6b7a3a)\"><strong>Maigreur constitutionnelle</strong> <em>(à distinguer)</em> — caractère familial fréquent.\n        <ul>\n          <li>Le poids <strong>a toujours été bas</strong> : pas d'évolutivité, poids stable, personne en bonne santé</li>\n          <li><span class=\"kw-clinique\">Masse</span> grasse abaissée (<span class=\"kw-chiffre\">&lt; 10 % chez l'homme</span>, <span class=\"kw-chiffre\">&lt; 15 % chez la femme</span>), <strong>force musculaire conservée</strong>, <span class=\"kw-chiffre\">IMC &gt; 16</span></li>\n          <li>Situation <strong>non pathologique</strong>, mais la faiblesse des réserves énergétiques implique :\n            <ul>\n              <li>Favorise l'<span class=\"kw-alerte\">ostéopénie</span></li>\n              <li>Plus grande <span class=\"kw-alerte\">fragilité</span> en situation de carence d'apports prolongée</li>\n            </ul>\n          </li>\n        </ul>\n      </div>","frequence":0},{"id":"251-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes d'une diminution des ingesta","contenu":"<p>La diminution des ingesta (mécanisme le plus fréquent) s'évalue par une <strong>quantification des apports alimentaires</strong>.</p>\n      <ul>\n        <li><span class=\"kw-clinique\"><strong>Relevé alimentaire</strong></span> sur <span class=\"kw-chiffre\">≥ 1 à 3 jours</span> par un diététicien (enquête rétrospective)</li>\n        <li><span class=\"kw-clinique\"><strong>EVA de la prise alimentaire</strong></span> avec <span class=\"kw-def\">score</span> <span class=\"kw-def\">SEFI</span> (Self Evaluation of Food Intake)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>En <span class=\"kw-alerte\">hospitalisation</span></strong> — les ingesta sont estimés par les <strong>plateaux repas</strong> :\n        <table >\n          <thead><tr><th>Prise observée</th><th>Apport estimé</th></tr></thead>\n          <tbody>\n            <tr><td>A tout mangé</td><td><span class=\"kw-chiffre\">1800 à 2000 kcal/jour</span></td></tr>\n            <tr><td>A mangé &gt;<span class=\"kw-chiffre\"> 50 %</span></td><td><span class=\"kw-chiffre\">&gt; 1000 kcal/jour</span></td></tr>\n            <tr><td>A mangé &lt;<span class=\"kw-chiffre\"> 50 %</span></td><td><span class=\"kw-chiffre\">&lt; 1000 kcal/jour</span></td></tr>\n            <tr><td>À jeun / n'a rien mangé</td><td><span class=\"kw-alerte\">0 kcal/jour</span></td></tr>\n          </tbody>\n        </table>\n      </div>","frequence":0},{"id":"251-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques évocateurs d'une malabsorption et/ou d'une maldigestion","contenu":"<div class=\"callout callout-info\"><strong><span class=\"kw-clinique\">Syndrome de malabsorption</span> / maldigestion</strong> = <span class=\"kw-def\">diarrhée</span> + <span class=\"kw-def\">syndrome carentiel</span>.</div>\n      <p>La <strong><span class=\"kw-clinique\">diarrhée</span></strong> évocatrice est :</p>\n      <ul>\n        <li>Trop <strong>fréquente</strong> : <span class=\"kw-chiffre\">&gt; 3/jour</span></li>\n        <li>Ou trop <strong>abondante</strong> : <span class=\"kw-chiffre\">&gt; 300 g/jour</span></li>\n        <li><strong>Molle, liquide ou grasse</strong> (<span class=\"kw-clinique\">stéatorrhée</span>)</li>\n        <li>Associée à des <strong>douleurs ou un inconfort digestif</strong></li>\n      </ul>\n      <p>S'y ajoutent les <strong>signes de dénutrition et de carences</strong> (syndrome carentiel) à rechercher cliniquement et biologiquement.</p>\n      <p class=\"obj-renvois\"><em>📎 Les examens de <span class=\"kw-def\">dépistage</span> à prescrire devant ces signes sont détaillés dans l'objectif suivant.</em></p>","frequence":0},{"id":"251-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités de prescription des examens de dépistage d'une malabsorption et/ou d'une maldigestion","contenu":"<p>Devant des symptômes digestifs, les explorations se font en <strong>trois étages</strong> : selles, sang, endoscopies.</p>\n\n      <p><strong>1 · Étude des selles</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Poids des selles sur 72 h</span> — <strong><span class=\"kw-clinique\">diarrhée</span> si &gt;<span class=\"kw-chiffre\"> 300 g</span>/jour</strong></li>\n        <li><span class=\"kw-clinique\">Temps de transit au rouge carmin</span> — <strong>accéléré si &lt;<span class=\"kw-chiffre\"> 8 h</span></strong></li>\n        <li><span class=\"kw-clinique\">Stéatorrhée</span> — pathologique si <span class=\"kw-chiffre\">&gt; 7 g de graisses/jour</span> dans les selles</li>\n        <li><span class=\"kw-clinique\">Élastase fécale</span> — abaissée en cas d'<strong>insuffisance pancréatique exocrine</strong></li>\n        <li><span class=\"kw-clinique\">Coproculture et parasitologie</span> des selles</li>\n        <li><span class=\"kw-clinique\">Calprotectine fécale</span> — augmentée si inflammation intestinale (<strong>MICI</strong>)</li>\n        <li><span class=\"kw-clinique\">Alpha-1 antitrypsine</span> — augmentée en cas d'<strong>entéropathie exsudative</strong></li>\n      </ul>\n\n      <p><strong>2 · Bilan sanguin</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">Hyperéosinophilie</span> — parasitose digestive à nématode</li>\n        <li><span class=\"kw-bio\">Test au D-xylose</span> — diminution de la xylosémie <span class=\"kw-chiffre\">2 h</span> après absorption = malabsorption des sucres</li>\n        <li><span class=\"kw-bio\">IgA anti-transglutaminase</span> — <strong>maladie cœliaque</strong></li>\n        <li>Recherche de <span class=\"kw-alerte\">carences</span> : <span class=\"kw-bio\">ferritine</span>, vitamines B9 et B12 (si pathologie gastrique et iléale), vitamines A et E, <span class=\"kw-bio\">TP</span> et facteur V (si stéatorrhée)</li>\n        <li><span class=\"kw-bio\">Citrulline plasmatique</span> — reflète la <span class=\"kw-clinique\">masse</span> entérocytaire fonctionnelle</li>\n        <li><span class=\"kw-alerte\">Hypoalbuminémie</span> — <span class=\"kw-alerte\">signe de gravité</span></li>\n      </ul>\n\n      <p><strong>3 · Endoscopies et imagerie</strong></p>\n      <ul>\n        <li><span class=\"kw-radio\">EOGD avec biopsie duodénale</span> — maladie cœliaque (atrophie villositaire)</li>\n        <li><span class=\"kw-radio\">Coloscopie avec iléoscopie et biopsies étagées</span> — MICI</li>\n        <li><span class=\"kw-radio\">Vidéocapsule</span> — si autres explorations endoscopiques négatives</li>\n        <li><span class=\"kw-radio\">Entéro-IRM et scanner abdomino-pelvien</span> — MICI</li>\n        <li><span class=\"kw-radio\">Test respiratoire à l'hydrogène</span> après ingestion de glucose — pullulation microbienne</li>\n      </ul>","frequence":0},{"id":"251-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le raisonnement diagnostique devant un amaigrissement","contenu":"<div class=\"callout callout-info\"><strong>Trois questions à se poser systématiquement :</strong> <span class=\"kw-def\">Confirmer</span> · <span class=\"kw-def\">Étiologie</span> · <span class=\"kw-def\">Gravité</span>.</div>\n\n      <table >\n        <thead><tr><th>Temps</th><th>Démarche clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Confirmer</strong></span></td>\n            <td>Affirmer l'<span class=\"kw-clinique\">amaigrissement</span> par la <strong>pesée</strong> (perte en %) ; <span class=\"kw-alerte\">5 kg toujours significatif</span> ; chez l'enfant, analyser les courbes de poids et de taille</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Étiologie ?</strong></span></td>\n            <td>Évaluer les ingesta (relevé, SEFI, plateaux repas) ; rechercher une malabsorption (<span class=\"kw-clinique\">diarrhée</span> + syndrome carentiel) ; rechercher des signes d'orientation</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Gravité ?</strong></span></td>\n            <td>Évaluer le retentissement et rechercher une sarcopénie + des <strong>OMI</strong> (dénutrition protéique sévère 🔥)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p style=\"margin-top:18px\"><strong>Interrogatoire</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">ATCD</span> médicaux et chirurgicaux</li>\n        <li><span class=\"kw-clinique\">Addictions</span></li>\n        <li><span class=\"kw-clinique\">Médicaments</span></li>\n        <li><span class=\"kw-clinique\">Contexte</span> familial et socioprofessionnel</li>\n        <li>État <span class=\"kw-clinique\">psychologique et psychiatrique</span></li>\n        <li>Recherche de <strong>facteurs aggravants</strong> : troubles digestifs, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">fièvre</span>, polyurie…</li>\n        <li>🔥 Chez l'enfant : rechercher une <strong>cassure de la courbe staturale associée</strong></li>\n      </ul>\n\n      <p><strong>Examen clinique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Palpation</span> abdominale, ganglionnaire, <strong>toucher pelvien</strong>, <span class=\"kw-clinique\">hépatosplénomégalie</span>, <span class=\"kw-clinique\">fièvre</span></li>\n        <li>Pathologie de la <span class=\"kw-clinique\">cavité buccale</span> et de la <span class=\"kw-clinique\">déglutition</span></li>\n        <li>Trouble neurologique (ROT, déficit moteur)</li>\n        <li>Recherche d'une <span class=\"kw-clinique\">sarcopénie</span> = ↓ de la <strong>force</strong> musculaire (dynamomètre / hand grip) et/ou de la <strong>fonction</strong> musculaire (vitesse de marche sur 4 m)</li>\n        <li><span class=\"kw-alerte\">OMI</span></li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong>🚩 Évaluation du retentissement / gravité</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Hypotension</span>, <span class=\"kw-alerte\">bradycardie &lt; 50 bpm</span></li>\n          <li><span class=\"kw-clinique\">Hypothermie</span></li>\n          <li><span class=\"kw-clinique\">Asthénie</span> et ralentissement psychomoteur</li>\n          <li><span class=\"kw-clinique\">Constipation</span></li>\n          <li>Trouble du <span class=\"kw-clinique\">cycle menstruel</span></li>\n          <li><span class=\"kw-alerte\">Hypoglycémie symptomatique</span> (notamment si IMC &lt; 13)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\"><strong>Examens complémentaires</strong> — bilan à réaliser devant un <em><span class=\"kw-clinique\">amaigrissement</span> involontaire isolé sans orientation</em> :\n        <p style=\"margin:8px 0 4px\"><strong>Biologie</strong></p>\n        <ul>\n          <li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatininémie</span></li>\n          <li><span class=\"kw-bio\">Calcémie</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">albumine</span>, transthyrétine, <span class=\"kw-bio\">TSH</span> ultrasensible</li>\n          <li>IDR à la tuberculine, <span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">VIH</span></li>\n          <li>Bandelette urinaire</li>\n        </ul>\n        <p style=\"margin:8px 0 4px\"><strong>Imagerie</strong></p>\n        <ul>\n          <li><span class=\"kw-imagerie\">RXT</span> ou <span class=\"kw-imagerie\">TDM</span> thoracique</li>\n          <li><span class=\"kw-imagerie\">TDM</span> abdomino-pelvien ou <span class=\"kw-imagerie\">échographie</span> AP</li>\n          <li>Radiocinéma de la déglutition (si sujet âgé ou pathologie neurologique)</li>\n        </ul>\n      </div>\n\n      <p style=\"margin-top:18px\"><strong>Orientation étiologique selon le comportement alimentaire</strong></p>\n\n      <div class=\"callout callout-info\" style=\"border-left:4px solid var(--spe-infectio,#b8472c)\"><strong>① Restriction alimentaire involontaire</strong>\n        <ul>\n          <li><strong>Si <span class=\"kw-clinique\">fièvre</span></strong> : infection (<span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">VIH</span>, EI subaiguë), inflammation (Horton), cancer (lymphome, hémopathie, rein, foie)</li>\n          <li><strong>Si apyrétique</strong> : néoplasie profonde, maladie <span class=\"kw-etio\">inflammatoire</span>, cause métabolique, atteinte neurologique</li>\n          <li><span class=\"kw-alerte\">Syndrome dépressif</span> : évoqué si signes dépressifs, mais c'est un <strong>diagnostic d'exclusion</strong></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\" style=\"border-left:4px solid var(--spe-neuro,#8a4a7f)\"><strong>② Restriction alimentaire volontaire</strong>\n        <ul>\n          <li>Régime restrictif : raisons médicales (maladies de surcharge), esthétiques, revendicatrices (grève de la faim)</li>\n          <li><span class=\"kw-clinique\">Anorexie mentale, TCA</span></li>\n          <li>Pathologie digestive, ORL ou stomatologique → dysgueusie, odynophagie, dysphagie aux solides, troubles de la déglutition, fausses routes, dyspepsie, douleur abdominale</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\" style=\"border-left:4px solid var(--spe-cardio,#2f5e6b)\"><strong>③ Pas de restriction alimentaire, voire hyperphagie</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Diabète sucré insulinopénique</span></li>\n          <li><span class=\"kw-clinique\">Hyperthyroïdie</span>, <span class=\"kw-clinique\">phéochromocytome</span></li>\n          <li>Maladie d'Addison, insuffisance antéhypophysaire (plus rares)</li>\n          <li>Syndrome du <span class=\"kw-clinique\">grêle court</span> (ATCD de résections intestinales)</li>\n          <li>Parasitoses intestinales</li>\n          <li><span class=\"kw-alerte\">Néoplasie</span> — toujours y penser dans ce contexte</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\"><strong>Cas particulier — sujet âgé.</strong> L'<span class=\"kw-clinique\">amaigrissement</span> est souvent <span class=\"kw-clinique\">dépressif</span> (isolement) avec <span class=\"kw-ttt\">réduction</span> des apports, mais doit <strong>impérativement faire rechercher une pathologie organique sévère</strong> (néoplasie, maladie <span class=\"kw-etio\">inflammatoire</span>), du fait du <span class=\"kw-alerte\">risque majeur de dénutrition</span>.</div>\n\n      <div class=\"callout callout-danger\"><strong>🔥 Aucune étiologie n'est retrouvée dans <span class=\"kw-chiffre\">20 %</span> des cas</strong> → <strong><span class=\"kw-def\">suivi</span> +++</strong>.</div>","frequence":4}],"astuces":[],"strategie":{"hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-clinique\">amaigrissement</span> isolé sans <span class=\"kw-alerte\">signe de gravité</span>, avec bilan étiologique orienté par l'examen.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> en cas de <span class=\"kw-etio\">dénutrition sévère</span> — pesée <span class=\"kw-chiffre\">à l'admission puis hebdomadaire</span> (voire <span class=\"kw-chiffre\">quotidienne</span> chez l'enfant dénutri sévère).<br><strong>Sujet âgé :</strong> <span class=\"kw-alerte\">risque majeur de dénutrition</span> — rechercher impérativement une <span class=\"kw-etio\">pathologie organique sévère</span> (néoplasie, maladie <span class=\"kw-etio\">inflammatoire</span>), même devant un contexte dépressif d'isolement.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Bradycardie &lt; 50 bpm</span> et <span class=\"kw-clinique\">hypotension</span></li><li><span class=\"kw-alerte\">Hypothermie</span></li><li><span class=\"kw-alerte\">Hypoglycémie symptomatique</span> (notamment si <span class=\"kw-chiffre\">IMC &lt; 13</span>)</li><li><span class=\"kw-clinique\">Asthénie</span> et <span class=\"kw-clinique\">ralentissement psychomoteur</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">troubles du cycle menstruel</span></li><li><span class=\"kw-alerte\">Œdèmes des membres inférieurs (OMI)</span> → traduisent une <span class=\"kw-etio\">dénutrition protéique sévère</span></li><li><span class=\"kw-bio\">Hypoalbuminémie</span> — <span class=\"kw-alerte\">signe de gravité</span></li><li>Chez l'enfant : <span class=\"kw-alerte\">cassure de la courbe staturale</span> associée</li></ul>","principes":"<p>La prise en charge initiale repose sur une <span class=\"kw-def\">démarche diagnostique structurée</span> en trois temps : confirmer, évaluer les ingesta, orienter l'étiologie et la gravité.</p><p><strong>1 · Confirmer l'<span class=\"kw-clinique\">amaigrissement</span></strong></p><p>Éliminer une <span class=\"kw-etio\">maigreur constitutionnelle</span> (poids stable, <span class=\"kw-chiffre\">IMC &gt; 16</span>) et une perte par <span class=\"kw-clinique\">mouvement hydrique</span> (<span class=\"kw-clinique\">œdème</span> ≠ <span class=\"kw-clinique\">amaigrissement</span>).</p><ul><li><span class=\"kw-ttt\">Pesée fiable</span> (vessie vide, en sous-vêtements) — perte exprimée en <span class=\"kw-chiffre\">% du poids habituel</span></li><li>Significatif si <span class=\"kw-chiffre\">&gt; 5 % en 1 mois</span>, <span class=\"kw-chiffre\">&gt; 10 % en 6 mois</span> ou <span class=\"kw-chiffre\">&gt; 10 %</span> du poids antérieur à la maladie</li><li><span class=\"kw-alerte\">Une perte de 5 kg est toujours significative</span></li><li>Chez l'enfant : analyser les <span class=\"kw-clinique\">courbes de poids et de taille</span></li></ul><p><strong>2 · Évaluer les ingesta et chercher une malabsorption</strong></p><ul><li><span class=\"kw-ttt\">Relevé alimentaire</span> sur <span class=\"kw-chiffre\">1 à 3 jours</span> par le diététicien, <span class=\"kw-ttt\">EVA</span> de la prise alimentaire (<span class=\"kw-def\">score</span> <span class=\"kw-bio\">SEFI</span>)</li><li>En <span class=\"kw-alerte\">hospitalisation</span> : estimation par les plateaux-repas (<span class=\"kw-chiffre\">&lt; 1000 kcal/j</span> si &lt;<span class=\"kw-chiffre\"> 50 %</span> du repas mangé)</li><li><span class=\"kw-etio\">Malabsorption / maldigestion</span> évoquée devant <span class=\"kw-clinique\">diarrhée</span> <span class=\"kw-chiffre\">&gt; 3/jour</span> ou <span class=\"kw-chiffre\">&gt; 300 g/jour</span>, molle ou grasse (<span class=\"kw-clinique\">stéatorrhée</span>) + syndrome carentiel</li></ul><p><strong>3 · Bilan étiologique (<span class=\"kw-clinique\">amaigrissement</span> isolé sans orientation)</strong></p><p>🔥 <span class=\"kw-alerte\">Aucune étiologie n'est retrouvée dans 20 % des cas</span> → <span class=\"kw-def\">surveillance</span> rapprochée.</p><ul><li><span class=\"kw-bio\">NFS, CRP, bilan hépatique, ionogramme, créatininémie</span></li><li><span class=\"kw-bio\">Calcémie, glycémie, albumine, transthyrétine, TSH ultrasensible</span></li><li><span class=\"kw-bio\">Sérologie VIH</span>, <span class=\"kw-ttt\">IDR à la tuberculine</span>, <span class=\"kw-bio\">bandelette urinaire</span></li><li>Imagerie : <span class=\"kw-imagerie\">RXT ou TDM thoracique</span>, <span class=\"kw-imagerie\">TDM ou échographie abdomino-pelvienne</span></li></ul>","suivi":"<p><strong>Pesée :</strong> <span class=\"kw-chiffre\">à l'admission puis hebdomadaire</span> en <span class=\"kw-alerte\">hospitalisation</span> (<span class=\"kw-chiffre\">quotidienne</span> si dénutrition sévère chez l'enfant).<br><strong>Sans étiologie :</strong> <span class=\"kw-alerte\">20 % des amaigrissements restent inexpliqués</span> → <span class=\"kw-ttt\">suivi rapproché +++</span> à la recherche d'une cause secondairement révélée.<br><strong>Paramètres :</strong> <span class=\"kw-clinique\">évolution</span> du <span class=\"kw-clinique\">poids</span> et de l'<span class=\"kw-bio\">albuminémie</span>, <span class=\"kw-clinique\">force et fonction musculaires</span> (hand-grip, vitesse de marche).</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Amaigrissement allégué — Pesée du patient","detail":"<h4>CAT — Démarche diagnostique devant un <span class=\"kw-clinique\">amaigrissement</span> — Confirmer → évaluer la gravité → orienter l'étiologie</h4>","branches":[{"to":"q-confirm","label":"Pesée","color":"blue"}]},{"id":"q-confirm","kind":"decision","label":"Perte de poids significative ? — >5 %/1 mois, >10 %/6 mois, ≥5 kg ou >10 % du poids antérieur","branches":[{"to":"t-constit","label":"Non — poids stable, IMC > 16","color":"green"},{"to":"q-gravite","label":"Oui — perte significative","color":"amber"}]},{"id":"t-constit","kind":"terminal","label":"Pas d'amaigrissement pathologique — Maigreur constitutionnelle / perte hydrique","color":"green","detail":"<h4>Clinique</h4><ul><li>Poids toujours bas et stable, <span class=\"kw-chiffre\">IMC &gt; 16</span>, <span class=\"kw-clinique\">force musculaire conservée</span>, <span class=\"kw-clinique\">masse</span> grasse basse (<span class=\"kw-chiffre\">&lt; 10 % homme</span>, <span class=\"kw-chiffre\">&lt; 15 % femme</span>)</li><li>Perte d'un <span class=\"kw-clinique\">œdème</span> : mouvement hydrique ≠ <span class=\"kw-clinique\">amaigrissement</span></li></ul><h4>Conduite</h4><ul><li>Situation <span class=\"kw-def\">non pathologique</span> ; surveiller la <span class=\"kw-alerte\">fragilité en cas de carence prolongée</span> et le risque d'<span class=\"kw-alerte\">ostéopénie</span></li></ul>"},{"id":"q-gravite","kind":"decision","label":"Signes de gravité / retentissement sévère ? — Red flags de dénutrition","branches":[{"to":"t-hospit","label":"Oui — red flags","color":"red"},{"to":"q-comportement","label":"Non","color":"amber"}]},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation — dénutrition sévère","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Bradycardie &lt; 50 bpm</span>, <span class=\"kw-alerte\">hypothermie</span>, <span class=\"kw-alerte\">hypoglycémie symptomatique</span> (<span class=\"kw-chiffre\">IMC &lt; 13</span>)</li><li><span class=\"kw-alerte\">OMI</span> → <span class=\"kw-etio\">dénutrition protéique sévère</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hypoalbuminémie</span> (<span class=\"kw-alerte\">signe de gravité</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Pesée <span class=\"kw-chiffre\">à l'admission puis hebdomadaire</span> (<span class=\"kw-chiffre\">quotidienne</span> chez l'enfant dénutri sévère)</li></ul>"},{"id":"q-comportement","kind":"decision","label":"Comportement alimentaire ? — Oriente le bilan étiologique","branches":[{"to":"q-fievre","label":"Restriction involontaire","color":"amber"},{"to":"t-volontaire","label":"Restriction volontaire","color":"amber"},{"to":"t-hyperphagie","label":"Pas de restriction / hyperphagie","color":"amber"}]},{"id":"q-fievre","kind":"decision","label":"Fièvre associée ? — Restriction alimentaire involontaire","branches":[{"to":"t-fievre","label":"Fièvre","color":"amber"},{"to":"t-apyret","label":"Apyrétique","color":"amber"}]},{"id":"t-fievre","kind":"terminal","label":"Cause infectieuse / inflammatoire / néoplasique","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Infection</span> : <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">VIH</span>, endocardite infectieuse subaiguë</li><li><span class=\"kw-etio\">Inflammation</span> : maladie de Horton</li><li><span class=\"kw-etio\">Cancer</span> : lymphome, hémopathie, rein, foie</li></ul>"},{"id":"t-apyret","kind":"terminal","label":"Néoplasie / maladie inflammatoire / cause métabolique ou neurologique","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Néoplasie profonde</span>, <span class=\"kw-etio\">maladie inflammatoire</span></li><li><span class=\"kw-etio\">Cause métabolique</span> ou <span class=\"kw-etio\">atteinte neurologique</span></li><li><span class=\"kw-alerte\">Syndrome dépressif</span> = diagnostic d'exclusion</li></ul>"},{"id":"t-volontaire","kind":"terminal","label":"Restriction alimentaire volontaire","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Anorexie mentale</span>, <span class=\"kw-etio\">TCA</span></li><li>Régime restrictif (raison médicale, esthétique, grève de la faim)</li><li>Pathologie <span class=\"kw-etio\">digestive / ORL / stomatologique</span> : dysgueusie, odynophagie, dysphagie aux solides, troubles de la déglutition</li></ul>"},{"id":"t-hyperphagie","kind":"terminal","label":"Pas de restriction / hyperphagie","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Diabète sucré insulinopénique</span></li><li><span class=\"kw-etio\">Hyperthyroïdie</span>, <span class=\"kw-etio\">phéochromocytome</span></li><li><span class=\"kw-etio\">Maladie d'Addison</span>, insuffisance antéhypophysaire</li><li><span class=\"kw-etio\">Syndrome du grêle court</span>, <span class=\"kw-etio\">parasitose intestinale</span> ; toujours penser à une <span class=\"kw-etio\">néoplasie</span></li></ul>"}]},"cards":[{"i":"52711f306d08","n":251,"o":"251-4","u":"Diagnostic positif","t":"Connaître les signes d'une diminution des ingesta","q":"Comment évalue-t-on une diminution des ingesta dans le bilan d'un amaigrissement en ambulatoire ?","a":"<p>La diminution des ingesta s'évalue principalement par une <strong>quantification des apports alimentaires</strong>.</p><ul><li>Un <strong>relevé alimentaire sur &ge; 1 à 3 jours</strong>, idéalement réalisé par un diététicien (enquête rétrospective).</li><li>L'utilisation d'une <strong>Échelle Visuelle Analogique (EVA) de la prise alimentaire</strong> comme le score SEFI (Self Evaluation of Food Intake).</li></ul>"},{"i":"5ae4ada039ca","n":251,"o":"251-4","u":"Diagnostic positif","t":"Connaître les signes d'une diminution des ingesta","q":"Comment les ingesta sont-ils estimés en milieu hospitalier pour détecter une diminution des apports ?","a":"<p>En hospitalisation, les ingesta sont estimés à partir de l'observation des <strong>plateaux repas</strong> :</p><ul><li><strong>A tout mangé</strong> : Apport estimé à <strong>1800 à 2000 kcal/jour</strong>.</li><li><strong>A mangé &gt; 50 %</strong> du plateau : Apport estimé à <strong>&gt; 1000 kcal/jour</strong>.</li><li><strong>A mangé &lt; 50 %</strong> du plateau : Apport estimé à <strong>&lt; 1000 kcal/jour</strong>.</li><li><strong>À jeun / n'a rien mangé</strong> : Apport de <strong>0 kcal/jour</strong>.</li></ul>"},{"i":"4261324fd152","n":251,"o":"251-7","u":"Diagnostic positif","t":"Connaître le raisonnement diagnostique devant un amaigrissement","q":"Comment doit-on confirmer un amaigrissement chez l'adulte et chez l'enfant ?","a":"<p>Pour confirmer un amaigrissement :</p><ul><li>Chez l'adulte : l'affirmer par la <strong>pesée</strong> (perte en %) ; une perte de <strong>5 kg</strong> est toujours significative.</li><li>Chez l'enfant : l'analyser sur les <strong>courbes de poids et de taille</strong>, en recherchant notamment une <strong>cassure de la courbe staturale</strong> associée.</li></ul>"},{"i":"c60dd7b26ea5","n":251,"o":"251-7","u":"Diagnostic positif","t":"Connaître le raisonnement diagnostique devant un amaigrissement","q":"Quels sont les examens complémentaires de première intention à réaliser devant un amaigrissement involontaire isolé et sans orientation étiologique initiale ?","a":"<p>Devant un amaigrissement involontaire isolé sans orientation, le bilan biologique initial comprend :</p><ul><li><strong>NFS</strong>, <strong>CRP</strong>, <strong>bilirubine</strong>, <strong>transaminases</strong>, <strong>GGT</strong>, <strong>phosphatases alcalines</strong>.</li><li><strong>Ionogramme sanguin</strong>, <strong>créatininémie</strong>.</li><li><strong>Calcémie</strong>, <strong>glycémie</strong>, <strong>albumine</strong>, <strong>transthyrétine</strong>, <strong>TSH ultrasensible</strong>.</li><li><strong>IDR à la tuberculine</strong>, <strong>sérologie VIH</strong>.</li><li><strong>Bandelette urinaire</strong>.</li></ul><p>Les examens d'imagerie incluent :</p><ul><li><strong>RXT</strong> ou <strong>TDM thoracique</strong>.</li><li><strong>TDM abdomino-pelvien</strong> ou <strong>échographie abdominale et pelvienne</strong>.</li><li>Un <strong>radiocinéma de la déglutition</strong> si le sujet est âgé ou présente une pathologie neurologique.</li></ul>"},{"i":"eeb78c3750b5","n":251,"o":"251-7","u":"Diagnostic positif","t":"Connaître le raisonnement diagnostique devant un amaigrissement","q":"Quelles sont les principales orientations étiologiques à considérer en fonction du comportement alimentaire face à un amaigrissement ?","a":"<p>Les orientations étiologiques peuvent être classées selon le comportement alimentaire :</p><ul><li><strong>Restriction alimentaire involontaire</strong> :<ul><li>Si <strong>fièvre</strong> : infections (<strong>tuberculose</strong>, <strong>VIH</strong>, <strong>endocardite infectieuse subaiguë</strong>), inflammation (<strong>Horton</strong>), cancers (lymphome, hémopathie, rein, foie).</li><li>Si <strong>apyrétique</strong> : néoplasie profonde, maladie inflammatoire, cause métabolique, atteinte neurologique.</li><li>Syndrome dépressif (diagnostic d'exclusion).</li></ul></li><li><strong>Restriction alimentaire volontaire</strong> :<ul><li>Régimes restrictifs (médicaux, esthétiques, revendicateurs).</li><li><strong>Anorexie mentale</strong>, <strong>TCA</strong>.</li><li>Pathologies digestives, ORL ou stomatologiques (dysgueusie, odynophagie, dysphagie, troubles de la déglutition, fausses routes, dyspepsie, douleur abdominale).</li></ul></li><li><strong>Pas de restriction alimentaire, voire hyperphagie</strong> :<ul><li><strong>Diabète sucré insulinopénique</strong>.</li><li><strong>Hyperthyroïdie</strong>, <strong>phéochromocytome</strong>.</li><li>Maladie d'Addison, insuffisance antéhypophysaire (plus rares).</li><li><strong>Syndrome du grêle court</strong>.</li><li><strong>Parasitoses intestinales</strong>.</li><li><strong>Néoplasie</strong> (toujours à considérer).</li></ul></li></ul>"},{"i":"fa0e1346fe73","n":251,"o":"251-7","u":"Diagnostic positif","t":"Connaître le raisonnement diagnostique devant un amaigrissement","q":"Quelles sont les particularités de l'amaigrissement chez le sujet âgé et quelle est la conduite à tenir ?","a":"<p>Chez le sujet âgé, l'amaigrissement est souvent dû à un syndrome dépressif, fréquemment associé à l'isolement, entraînant une réduction des apports. Cependant, il doit impérativement faire rechercher une <strong>pathologie organique sévère</strong> (<strong>néoplasie</strong>, <strong>maladie inflammatoire</strong>) en raison du risque majeur de <strong>dénutrition</strong> et de ses complications. Dans <strong>20% des cas</strong>, aucune étiologie n'est retrouvée, justifiant alors un <strong>suivi rigoureux</strong>.</p>"},{"i":"facee5a1845a","n":251,"o":"251-7","u":"Diagnostic positif","t":"Connaître le raisonnement diagnostique devant un amaigrissement","q":"Quelles sont les trois questions fondamentales à se poser systématiquement devant un amaigrissement, selon le raisonnement diagnostique ?","a":"<p>Devant un amaigrissement, il faut systématiquement se poser les questions suivantes :</p><ul><li><strong>Confirmer</strong> l'amaigrissement.</li><li>Rechercher son <strong>étiologie</strong>.</li><li>Évaluer sa <strong>gravité</strong>.</li></ul>"},{"i":"fe9e6ffbb1a5","n":251,"o":"251-7","u":"Diagnostic positif","t":"Connaître le raisonnement diagnostique devant un amaigrissement","q":"Quels sont les éléments cliniques à rechercher spécifiquement à l'interrogatoire et à l'examen physique dans le diagnostic étiologique d'un amaigrissement ?","a":"<p>À l'interrogatoire, il faut rechercher :</p><ul><li>Les <strong>ATCD médicaux et chirurgicaux</strong>.</li><li>Les <strong>addictions</strong> et les <strong>médicaments</strong>.</li><li>Le <strong>contexte familial et socioprofessionnel</strong>, ainsi que l'<strong>état psychologique et psychiatrique</strong>.</li><li>Des signes pouvant orienter vers un amaigrissement : <strong>troubles digestifs</strong>, <strong>tachycardie</strong>, <strong>dyspnée</strong>, <strong>fièvre</strong>, <strong>polyurie</strong>.</li></ul><p>À l'examen clinique, les points clés sont :</p><ul><li>La <strong>palpation abdominale</strong>, <strong>ganglionnaire</strong>, le <strong>toucher pelvien</strong>, la recherche d'une <strong>hépatosplénomégalie</strong>.</li><li>L'examen de la <strong>cavité buccale et de la déglutition</strong>.</li><li>La recherche de <strong>troubles neurologiques</strong> (ROT, déficit moteur).</li><li>La recherche d'une <strong>sarcopénie</strong> (diminution de la force musculaire au dynamomètre/hand grip ou de la fonction musculaire par la vitesse de marche).</li><li>La présence d'<strong>œdèmes des membres inférieurs (OMI)</strong>, signe de dénutrition protéique sévère.</li></ul>"}]};